INSERT INTO `pages` (`id`,`slug`,`title`,`content`,`meta_title`,`meta_description`,`sort_order`,`is_active`,`created_at`,`updated_at`) VALUES ('1','about','О компании','<h2>О компании</h2>\n<p>HUAWEI Enterprise — поставщик серверного оборудования и корпоративных решений HUAWEI для бизнеса.\nРаботаем с интеграторами, дата-центрами и предприятиями по всей России. Подбираем конфигурации под задачи,\nсогласовываем сроки поставки и сопровождаем проект от запроса до ввода в эксплуатацию.</p>\n\n<h2>Что мы делаем</h2>\n<ul>\n<li>Подбор серверов, СХД и сетевого оборудования HUAWEI под задачу;</li>\n<li>Расчёт конфигураций под нагрузку и бюджет;</li>\n<li>Доставка по России и сопровождение сделки;</li>\n<li>Консультации по лицензированию и гарантии.</li>\n</ul>\n\n<h2>Почему HUAWEI Enterprise</h2>\n<p>Оборудование HUAWEI — это высокая плотность вычислений, энергоэффективность и современная\nплатформа управления. Мы помогаем собрать действительно подходящую конфигурацию, а не «коробочное»\nрешение из прайса.</p>\n\n<p>По любым вопросам — <a href=\"/contacts\">напишите нам</a> или закажите <a href=\"/contacts\">обратный звонок</a>.</p>','О компании — HUAWEI Enterprise','Поставщик серверного оборудования HUAWEI Enterprise: подбор конфигураций, доставка по России, сопровождение проектов.','10','1','2026-09-21 16:07:36','2026-09-21 16:07:36');
INSERT INTO `pages` (`id`,`slug`,`title`,`content`,`meta_title`,`meta_description`,`sort_order`,`is_active`,`created_at`,`updated_at`) VALUES ('4','contacts','Контакты','<div class=\"contacts\">\n    <div class=\"contacts__card\">\n        <h2>Телефон</h2>\n        <p><a class=\"contacts__phone\" href=\"tel:+74951203040\">+7 (495) 120-30-40</a></p>\n    </div>\n    <div class=\"contacts__card\">\n        <h2>E-mail</h2>\n        <p><a class=\"contacts__email\" href=\"mailto:info@huawei-enterprise.ru\">info@huawei-enterprise.ru</a></p>\n    </div>\n    <div class=\"contacts__card\">\n        <h2>Адрес</h2>\n        <p><address class=\"contacts__addr\">г. Москва, Складской проезд, д. 1, стр. 2</address></p>\n    </div>\n    <div class=\"contacts__card\">\n        <h2>Режим работы</h2>\n        <p class=\"contacts__hours\">Пн–Пт: 9:00–18:00 (МСК)</p>\n    </div>\n</div>','Контакты — HUAWEI Enterprise','Телефон, e-mail и адрес HUAWEI Enterprise. Консультации по серверному оборудованию HUAWEI Enterprise.','20','1','2026-09-21 16:36:21','2026-09-21 16:36:21');
